// niche_intel/bank.mjs - topic bank: >=150 candidate ideas per channel,
// classified by content pillar. Ideas are GENERATED BY GEMINI inside the
// niche-research workflow (owner spec: never from the builder's memory).
// Unverified ideas stay `pending` and are only picked when no validated
// alternative exists, and are flagged in the report.
import {mkdir, readFile, writeFile, readdir} from 'node:fs/promises';
import path from 'node:path';

export async function loadBank(dir = 'topic_bank') {
  let files = [];
  try { files = (await readdir(dir)).filter(f => f.endsWith('.json')); } catch (e) { if (e.code !== 'ENOENT') throw e; }
  const ideas = [];
  for (const f of files) {
    const rows = JSON.parse(await readFile(path.join(dir, f), 'utf8'));
    for (const r of rows) ideas.push({...r, _file: f});
  }
  return ideas;
}

export async function saveBank(dir, ideas, {byPillar = true} = {}) {
  await mkdir(dir, {recursive: true});
  const groups = {};
  for (const idea of ideas) (groups[byPillar ? (idea.pillar || 'misc') : 'all'] ||= []).push(idea);
  for (const [g, rows] of Object.entries(groups)) {
    await writeFile(path.join(dir, g + '.json'), JSON.stringify(rows, null, 2) + '\n');
  }
}

// Generate seed ideas via Gemini from the channel profile. Returns
// {ok, ideas} - all status `pending` until demand/competition data validates
// them. No numeric fields are written here (rule: no numbers without a fetch).
export async function generateIdeas(profile, existing, geminiClient, {target = 150} = {}) {
  if (!geminiClient) return {ok: false, reason: 'no_gemini', note: 'bank stays as-is until GEMINI_API_KEY is available in CI'};
  const pillars = profile.pillars.map(p => p.id + ' (' + p.title + ')').join(', ');
  const have = new Set(existing.map(i => i.title));
  const r = await geminiClient.call({
    name: 'topic-bank-seed', stage: 'niche-intel', maxOutputTokens: 16000,
    system: 'You generate topic ideas for an Arabic YouTube Shorts channel. JSON only. Honest, curiosity-driven, never misleading.',
    user: 'Channel: ' + profile.channel + '\nAudience: ' + profile.audience + '\nPillars: ' + pillars + '\nSearch intent: ' + profile.searchIntent + '\nBanned: ' + (profile.bannedTopics || []).join(', ') +
      '\nExisting titles (do not repeat): ' + [...have].slice(0, 300).join(' | ') +
      '\nGenerate ' + target + ' ideas. Each: {"title": "<Arabic, phrased as a search-style question when possible>", "pillar": "<pillar id>", "primaryKeyword": "<main Arabic search term>", "secondaryKeyword": "<or empty>", "searchIntent": "informational|curiosity|entertainment", "kind": "evergreen|trending|seasonal", "wikiArticle": "<best Arabic Wikipedia article title for demand measurement, or empty>"}. Return {"ideas": [...]}.',
    schema: {type: 'OBJECT', properties: {ideas: {type: 'ARRAY', items: {type: 'OBJECT', properties: {title: {type: 'STRING'}, pillar: {type: 'STRING'}, primaryKeyword: {type: 'STRING'}, secondaryKeyword: {type: 'STRING'}, searchIntent: {type: 'STRING'}, kind: {type: 'STRING'}, wikiArticle: {type: 'STRING'}}, required: ['title', 'pillar', 'primaryKeyword', 'kind']}}}, required: ['ideas']},
  });
  if (!r.ok) return {ok: false, reason: r.reason};
  const ideas = (r.data.ideas || [])
    .filter(i => i.title && i.primaryKeyword && !have.has(i.title))
    .map(i => ({...i, status: 'pending', source: 'gemini:' + (r.model || 'unknown'), addedAt: new Date().toISOString()}));
  return {ok: true, ideas};
}

// 60-day no-repeat + pillar diversity (same pillar max twice in a row),
// from recent selections recorded in state/niche/*.json. Pure function.
export function passesDiversity(candidate, recentPicks, {noRepeatDays = 60, now = Date.now()} = {}) {
  for (const p of recentPicks) {
    if (p.title === candidate.title && now - Date.parse(p.date) < noRepeatDays * 86400000) return {ok: false, reason: 'DUPLICATE_WITHIN_60D'};
  }
  const last2 = recentPicks.slice(0, 2);
  if (candidate.pillar && last2.length === 2 && last2.every(p => p.pillar === candidate.pillar)) return {ok: false, reason: 'PILLAR_THRICE_IN_A_ROW'};
  return {ok: true};
}
